async ({ item, data, Apify }) => {
    const store = await Apify.openKeyValueStore('scraped-companies-master-list');
    const placeId = item.placeId || item.id;
    const companyName = (item.title || item.name || '').trim().toLowerCase();

    if (!placeId && !companyName) return item;

    const nameKey = 'name_' + companyName.replace(/[^a-z0-9]+/g, '_').replace(/(^_|_$)/g, '');

    if (placeId) {
        const alreadyScraped = await store.getValue(placeId);
        if (alreadyScraped) {
            console.log(`Skipping duplicate (placeId): ${item.title || item.name}`);
            return null;
        }
    }

    const nameMatch = await store.getValue(nameKey);
    if (nameMatch) {
        if (placeId && !nameMatch.placeId) {
            nameMatch.placeId = placeId;
            nameMatch.dateUpdated = new Date().toISOString();
            await store.setValue(nameKey, nameMatch);
            await store.setValue(placeId, {
                name: item.title || item.name,
                dateScraped: nameMatch.dateScraped,
                dateUpdated: new Date().toISOString(),
                source: 'backfilled'
            });
            console.log(`Backfilled placeId for: ${item.title || item.name}`);
        } else {
            console.log(`Skipping duplicate (name): ${item.title || item.name}`);
        }
        return null;
    }

    const record = {
        name: item.title || item.name,
        placeId: placeId || null,
        dateScraped: new Date().toISOString(),
        source: 'google-maps-actor'
    };

    if (placeId) {
        await store.setValue(placeId, record);
    }
    await store.setValue(nameKey, record);

    const runLog = await store.getValue('_run_log') || [];
    const runId = process.env.APIFY_DEFAULT_KEY_VALUE_STORE_ID || 'unknown';
    const exists = runLog.find(r => r.storeId === runId);
    if (!exists) {
        runLog.push({
            storeId: runId,
            timestamp: new Date().toISOString(),
            search: 'google-maps-actor'
        });
        await store.setValue('_run_log', runLog);
    }

    const dataset = await Apify.openDataset('latest-new-companies');
    await dataset.pushData({
        name: item.title || item.name,
        placeId: placeId || null,
        website: item.website || item.url || null,
        address: item.address || null,
        phone: item.phone || null,
        dateFound: new Date().toISOString()
    });

    return item;
}
